void fragment_peptide(const char* seq, int len,
                      double* b_ions, double* y_ions, double* precursor) {
    double mass = 0;
    for (int i = 0; i < len; i++) {
        mass += aa_mass(seq[i]);
        b_ions[i] = mass;
    }
    *precursor = mass + 18.01;
    for (int i = 0; i < len; i++)
        y_ions[len-1-i] = *precursor - b_ions[i] + 1.01;
}

