// the vocabulary. Sampling builds the tactic stream the kernel verifies.
func llmPredictNextToken(context []string) ProbDist {
	// Neural-network inference producing token likelihoods.
	return ProbDist{"theorem": 0.45, "proof": 0.30, "lemma": 0.15, "sorry": 0.10}
}

// LeanKernel applies strict, deterministic rules of inference.
type LeanKernel interface {
	CheckTactic(hypothesis, tactic string) bool
}

// AlphaProof loop: LLM proposes, kernel judges, verified steps are kept.
func alphaProof(goal string, kernel LeanKernel, maxSteps int) bool {
	ctx := []string{"theorem", goal}
	for i := 0; i < maxSteps; i++ {
		dist := llmPredictNextToken(ctx)
		tactic := topToken(dist)
		if kernel.CheckTactic(goal, tactic) {
			ctx = append(ctx, tactic)
			if tactic == "qed" {
				return true // proof certified, no human review
			}
		} else {
			ctx = append(ctx, "sorry") // backtrack / replan
		}
