type Context = List[String]
type ProbDist = Map[String, Double]

// The LLM is a function context -> probability distribution over the
// vocabulary. Sampling builds the tactic stream the kernel verifies.
def llmPredictNextToken(context: Context): ProbDist =
  Map("theorem" -> 0.45, "proof" -> 0.30, "lemma" -> 0.15, "sorry" -> 0.10)

// The Lean kernel applies strict, deterministic rules of inference and
// returns true/false. No human review is needed to certify a proof.
trait LeanKernel {
  def checkTactic(hypothesis: String, tactic: String): Boolean
}

// AlphaProof loop: LLM proposes, kernel judges, verified steps are kept.
@annotation.tailrec
final def alphaProof(goal: String, kernel: LeanKernel,
                      ctx: Context = List("theorem", goal),
                      step: Int = 0, maxSteps: Int = 1000): Boolean =
  if (step >= maxSteps) false
  else {
    val dist = llmPredictNextToken(ctx)
    val tactic = dist.maxBy(_._2)._1
    if (kernel.checkTactic(goal, tactic))
      if (tactic == "qed") true              // proof certified
      else alphaProof(goal, kernel, ctx :+ tactic, step + 1, maxSteps)
    else alphaProof(goal, kernel, ctx :+ "sorry", step + 1, maxSteps) // backtrack
  }

