/* Deterministic Lean kernel verifier: applies strict rules of inference. */
typedef struct { const char *tok; double p; } TokenProb;

/* The LLM is a function context -> probability distribution over the
 * vocabulary. Sampling builds the tactic stream the kernel verifies. */
static TokenProb *llm_predict_next_token(const char **context, int n) {
    (void)context; (void)n;
    static TokenProb dist[] = {
        {"theorem", 0.45}, {"proof", 0.30},
        {"lemma", 0.15},  {"sorry", 0.10}, {NULL, 0}
    };
    return dist;
}

typedef bool (*lean_check_fn)(const char *hyp, const char *tactic);

/* AlphaProof loop: LLM proposes, kernel judges, verified steps kept. */
bool alpha_proof(const char *goal, lean_check_fn kernel, int max_steps) {
    for (int i = 0; i < max_steps; i++) {
        TokenProb *dist = llm_predict_next_token(NULL, 0);
        const char *tactic = dist[0].tok;   /* greedy; beam search in practice */
        if (kernel(goal, tactic)) {
            if (strcmp(tactic, "qed") == 0) return true;  /* certified */
        }
        /* on failure: backtrack / replan (context.append(sorry)) */
    }
    return false;
}

