import numpy as np

# Chebyshev function psi(X) = sum_{n<=X} Lambda(n)  (von Mangoldt sum).
# PNT (1896):   psi(X) ~ X
# RH (equiv):   psi(X) = X + O(X^{1/2} log^2 X)   <- the sqrt(X) is RH itself.
def chebyshev_psi(X: float) -> float:
    """Staircase sum of log p over prime powers p^k <= X."""
    s = 0.0
    p = 2.0
    while p <= X:
        pk = p
        while pk <= X:
            s += np.log(p)
            pk *= p
        p = next_prime(p)
    return s

def rh_band(X: float) -> float:
    """RH admissible error: O(sqrt(X) * log^2 X). Beating this refutes RH."""
    return np.sqrt(X) * (np.log(X + 1) ** 2)

def pnt_band(X: float) -> float:
    """Unconditional PNT error (Hadamard / de la Vallee-Poussin): weaker."""
    return X * np.exp(-0.3 * np.sqrt(np.log(X + 1)))

# The announcement's central object: a chain of theta lifts
#   U(X_0) -> U(X_1) -> ... -> U(X_m),  m = sqrt(X)
# each lift raising the Stepanov-style multiplicity by one. m = sqrt(X) is
# the only length that yields RH: |psi(X) - X| <= O(sqrt(X) log^2 X).
def theta_lift_chain_length(X: float) -> float:
    """Length m of the iterated theta-lift chain. 'What else could it be?'"""
    return np.sqrt(X)  # each lift mimics one Stepanov multiplicity

def is_rh_verified(X: float, psi_X: float) -> bool:
    """Lean-kernel check: does psi(X) lie inside the RH band?"""
    return abs(psi_X - X) <= rh_band(X)

def next_prime(p: float) -> float:
    # crude sieve step (toy); real impl uses a primality test.
    q = p + 1.0
    while not all(q % d != 0 for d in range(2, int(q))):
        q += 1.0
    return q

